const btn = document.getElementById("addBtn");   // 1. امسك
btn.addEventListener("click", () => {             // 2. استنى الكبسة
  btn.textContent = "تمت الإضافة";               // 3. غيّر
});

const items = [
  { id: 1, name: "لاتيه", price: 2.5, image: "images/latte.jpg" },
  { id: 2, name: "موكا", price: 3, image: "images/mocha.jpg" }
];

const list = document.getElementById("list");
items.forEach(item => {
  list.innerHTML += `
    <div class="card">
      <img src="${item.image}" alt="${item.name}">
      <h3>${item.name}</h3>
      <p>${item.price} دينار</p>
    </div>`;
});
